      "explanation": "根据《生产经营单位生产安全事故应急预案编制导则》（GB/T29639-2020）的规定，应急预案体系包括综合应急预案、专项应急预案和现场处置方案。其中，专项应急预案是针对某一类型或某几种类型事故，或者针对重要生产设施、重大危险源、重大活动等内容而制定的应急预案。如果专项应急预案中的应急组织机构、应急响应程序等内容与综合应急预案中的内容相近或相同，导则允许在专项应急预案中直接引用综合应急预案的相关内容，而不必重复编写，以避免重复和矛盾，提高预案的协调性和可操作性。因此，原题中“即使……相近，也要单独编写”的说法不符合导则的要求，故该判断题为错误。"
