      "explanation": "《危险化学品安全管理条例》第七条负有危险化学品安全监督管理职责的部门依法进行监督检查，可以采取下列措施：（一）进入危险化学品作业场所实施现场检查，向有关单位和人员了解情况，查阅、复制有关文件、资料；（二）发现危险化学品事故隐患，责令立即消除或者限期消除；（三）对不符合法律、行政法规、规章规定或者国家标准、行业标准要求的设施、设备、装置、器材、运输工具，责令立即停止使用；（四）经本部门主要负责人批准，查封违法生产、储存、使用、经营危险化学品的场所，扣押违法生产、储存、使用、经营、运输的危险化学品以及用于违法生产、使用、运输危险化学品的原材料、设备、运输工具；（五）发现影响危险化学品安全的违法行为，当场予以纠正或者责令限期改正。负有危险化学品安全监督管理职责的部门依法进行监督检查，监督检查人员不得少于2人，并应当出示执法证件；有关单位和个人对依法进行的监督检查应当予以配合，不得拒绝、阻碍。"
