      "explanation": "《化工过程安全管理导则》（AQ/T3034—2022）4.8.2吹扫、清洗、气密（压力）试验安全进行吹扫、清洗、气密（压力）试验时，应编制清洗、吹扫、气密（压力）试验方案，落实责任人，按照方案组织实施，落实以下安全措施.a）吹扫清洗前，应确认吹扫清洗流程、介质及压力，并在排放口设置警戒区；b）选择水、空气、蒸汽对系统进行清洗、吹扫；使用介质、流量、流速、压力等参数及检验方法，应符合设计和规范的要求；c）不宜选择氮气作为吹扫介质，若必须使用氮气时，应明确防止氮气窒息的措施；d）蒸汽吹扫时，应落实防止人员烫伤的防护措施.e）化学清洗时，应落实防止化学品伤害的安全防护措施，配备必要的劳动防护用品；清洗废液应经处理后安全排放或作为危险废物进行合规处置；f）气密试验前应用盲板将气密试验系统与其他系统隔离，明确系统气密试验的最高压力等级，严禁超压；需对气密试验中发现的问题进行处理时，应先泄压，再进行处理。"
