      "explanation": "《生产经营单位生产安全事故应急预案编制导则》（GB/T29639-2020）5应急预案体系5.2综合应急预案综合应急预案是指生产经营单位为应对各种生产安全事故而制定的综合性工作方案，是本单位应对生产安全事故的总体工作程序、措施和应急预案体系的总纲。5.3专项应急预案专项应急预案是指生产经营单位为应对某一种或者多种类型生产安全事故，或者针对重要生产设施、重大危险源、重大活动防止生产安全事故而制定的专项工作方案。专项应急预案与综合应急预案中的应急组织机构、应急响应程序相近时，可不编写专项应急预案,相应的应急处置措施并入综合应急预案。5.4现场处置方案现场处置方案是指生产经营单位根据不同生产安全事故类型，针对具体场所、装置或者设施所制定的应急处置措施。现场处置方案重点规范事故风险描述、应急工作职责、应急处置措施和注意事项，应体现自救互救、信息报告和先期处置的特点。事故风险单一、危险性小的生产经营单位，可只编制现场处置方案。"
