      "explanation": "《国家安全监管总局关于公布首批重点监管的危险化学品名录的通知安监总管三〔2011〕95号》一、重点监管的危险化学品是指列入《名录》的危险化学品以及在温度20℃和标准大气压101.3kPa条件下属于以下类别的危险化学品：1.易燃气体类别1（爆炸下限≤13%或爆炸极限范围≥12%的气体）；2.易燃液体类别1（闭杯闪点<23℃并初沸点≤35℃的液体）；3.自燃液体类别1（与空气接触不到5分钟便燃烧的液体）；4.自燃固体类别1（与空气接触不到5分钟便燃烧的固体）；5.遇水放出易燃气体的物质类别1（在环境温度下与水剧烈反应所产生的气体通常显示自燃的倾向，或释放易燃气体的速度等于或大于每公斤物质在任何1分钟内释放10升的任何物质或混合物）；6.三光气等光气类化学品。"
